class Solution {
    static const int OFFSET = 1800;
    static const int SIZE = 3601;

    typedef bitset<SIZE> Bits;
    typedef array<Bits, 2> State;

public:
    int maxProduct(vector<int>& nums, int k, int limit) {
        if (k < -OFFSET || k > OFFSET)
            return -1;

        // dp[product][parity] stores reachable
        // alternating sums.
        // parity 0: next selected number is added.
        // parity 1: next selected number is subtracted.
        unordered_map<int, State> dp;

        // All subsequences, without product restriction.
        // Needed because multiplying by zero can turn
        // an oversized product into zero.
        State all;
        all[0].set(OFFSET); // Empty subsequence.

        for (int x : nums) {
            unordered_map<int, State> next = dp;

            // Start a new non-empty subsequence.
            if (x <= limit)
                next[x][1].set(OFFSET + x);

            // Extend existing subsequences.
            for (const auto& entry : dp) {
                int product = entry.first;
                long long newProduct = 1LL * product * x;

                if (newProduct > limit)
                    continue;

                const State& state = entry.second;
                State& dest = next[(int)newProduct];

                // Even selected index: add x.
                dest[1] |= (state[0] << x);

                // Odd selected index: subtract x.
                dest[0] |= (state[1] >> x);
            }

            // Zero can recover subsequences whose
            // previous product exceeded the limit.
            if (x == 0) {
                next[0][1] |= all[0];
                next[0][0] |= all[1];
            }

            // Update unrestricted reachability.
            State updated = all;

            updated[1] |= (all[0] << x);
            updated[0] |= (all[1] >> x);

            all = updated;
            dp.swap(next);
        }

        int ans = -1;
        int target = OFFSET + k;

        for (const auto& entry : dp) {
            int product = entry.first;
            const State& state = entry.second;

            if (state[0].test(target) ||
                state[1].test(target)) {
                ans = max(ans, product);
            }
        }

        return ans;
    }
};
